# v242: ricerca per gruppi di alimenti (generatore pasti, cambio alimento, diario)
import gb,asyncio
from playwright.async_api import async_playwright
D=open(gb.REPO+'/tools/demo/demo_data.json').read()
async def m():
  async with async_playwright() as p:
    b=await p.chromium.launch();pg=await b.new_page(viewport={'width':390,'height':844},device_scale_factor=2);E=[];pg.on('pageerror',lambda e:E.append(str(e)))
    await pg.add_init_script("if(!localStorage.getItem('gb-lang'))localStorage.setItem('gb-lang','it')")
    await pg.goto(gb.URL);await pg.wait_for_timeout(500)
    await pg.evaluate("(d)=>{norm(JSON.parse(d));save()}",D);await pg.reload();await pg.wait_for_timeout(700)
    ok=lambda c,w:print(('ok  ' if c else 'FAIL ')+w)
    r=await pg.evaluate("()=>['pesce','pesci','non mi piace il pesce','frutti di mare','carne rossa','formaggi','legumi','pesc','pasta'].map(q=>(fgOf(q)||[])[0]||null)")
    print(r);ok(r==['pesce','pesce','pesce','cm','cr','for','leg','pesce',None],'parole riconosciute')
    r=await pg.evaluate("()=>['pesce','pa','pb','cm','ps','cr','cb','mai','for','ff','fs','leg','glu'].map(id=>id+':'+fgMem(id).length+' '+fgMem(id).slice(0,4).map(f=>f.name).join('|'))");[print('  ',x) for x in r]
    await pg.evaluate("()=>{V.tab='pp';render()}");await pg.click('[data-a=mgo]');await pg.click('[data-a=mgn]');await pg.wait_for_timeout(150)
    await pg.fill('#mgbq','pesce');await pg.wait_for_timeout(150);await pg.screenshot(path=gb.O+'fg1.png',full_page=True)
    await pg.click('#mgbr .fgr.top');await pg.wait_for_timeout(150);await pg.click('.fgc');await pg.wait_for_timeout(150)
    await pg.click('[data-a=mgbe][data-v="Tonno al naturale"]');await pg.wait_for_timeout(150);await pg.screenshot(path=gb.O+'fg2.png',full_page=True)
    t=await pg.evaluate("()=>document.querySelector('.fgc').innerText");print(t);ok(' di ' in t,'chip del gruppo con eccezione')
    await pg.fill('#mgkq','legumi');await pg.wait_for_timeout(150);await pg.click('#mgkr .fgr.top');await pg.wait_for_timeout(150)
    await pg.click('[data-a=mgn]');await pg.click('[data-a=mgg]');await pg.wait_for_timeout(300)
    r=await pg.evaluate("()=>{const N=V.mg.G.W.flatMap(D=>MP.flatMap(m=>(D[m]||[]).map(y=>y.n)));return [N.filter(n=>fgHas('pesce',dpFood(n))),N.filter(n=>fgHas('leg',dpFood(n))).length]}")
    print(r);ok(all(n=='Tonno al naturale' for n in r[0]),'nessun pesce tranne l’eccezione');ok(r[1]>=5,'legumi frequenti')
    await pg.click('[data-a=mgsu]');await pg.click('[data-a=mgok]');await pg.wait_for_timeout(300)
    await pg.evaluate("()=>{const w=hvMon(today()),P=S.mpw[w],d=Object.keys(P).find(d=>P[d].Pranzo&&P[d].Pranzo.length),x=P[d].Pranzo.find(y=>fgHas('carne',fo(y.f))||fgHas('leg',fo(y.f)))||P[d].Pranzo[1];V.sw={k:'p',w,d:+d,m:'Pranzo',id:x.id,q:'legumi'};mpSwOpen()}")
    await pg.wait_for_timeout(200)
    r=await pg.evaluate("()=>[document.querySelector('.fgsw')&&document.querySelector('.fgsw').innerText,[...document.querySelectorAll('#swres .swi b')].map(x=>x.innerText).slice(0,4)]");print(r);ok(r[0] and 'Legumi' in r[0],'⇄ con «legumi» mostra il gruppo')
    await pg.fill('#swq','salmone');await pg.wait_for_timeout(200)
    t=await pg.evaluate("()=>document.querySelector('#swres').innerText");ok('nascost' in t and 'Salmone\n' not in t,'pesce nascosto dalle alternative')
    await pg.screenshot(path=gb.O+'fg3.png')
    await pg.evaluate("()=>{cfClose();V.tab='n';V.fsh='Pranzo';V.fq='formaggi';render()}");await pg.wait_for_timeout(200)
    r=await pg.evaluate("()=>[...document.querySelectorAll('#fl details summary')].map(x=>x.innerText).slice(0,5)");print(r);ok(any('Formaggi freschi' in x for x in r),'diario diviso per tipo')
    await pg.locator('#fl').screenshot(path=gb.O+'fg4.png')
    ok(not E,'nessun errore JS '+str(E));await b.close()
asyncio.run(m())
